import React, { Component } from "react";
import "./Header.css";
import LoginModal from "../LoginModal";

export default class Header extends Component {
  constructor(props) {
    super(props);
    this.state = {
      header1data: null,
      header2data: null,
      showLoginModal: false,
    };
  }

  componentDidMount() {
    this.fetchHeader1Menu();
    this.fetchHeader2Menu();
  }

  fetchHeader1Menu = () => {
    fetch(`http://localhost:3001/menupagesquary/1`, {
      method: 'POST',
      headers: {
        'Content-Type': 'application/json'
      },
      body: JSON.stringify({})
    })
      .then(response => response.json())
      .then(data => {
        this.setState({ header1data: data });
      })
      .catch(error => console.error('Error fetching data:', error));
  }

  fetchHeader2Menu = () => {
    fetch(`http://localhost:3001/menupagesquary/2`, {
      method: 'POST',
      headers: {
        'Content-Type': 'application/json'
      },
      body: JSON.stringify({})
    })
      .then(response => response.json())
      .then(data => {
        this.setState({ header2data: data });
      })
      .catch(error => console.error('Error fetching data:', error));
  }

  toggleLoginModal = () => {
    this.setState({ showLoginModal: !this.state.showLoginModal });
  }

  render() {
    const { header1data, header2data, showLoginModal } = this.state;
    if (!header1data) return <div>HEADER1 MENU DATA..</div>;
    if (!header2data) return <div>HEADER2 MENU DATA..</div>;

    return (
      <div>
        <nav>
          <ul>
            <li><h1 className="logo"><a href="/Homepage">{header1data.text}</a></h1></li>
          </ul>
          <ul>
            {header1data.filter(menuItem => menuItem.menuId === 1).map(headerMenu => (
              <li key={headerMenu.itemId}>
                <a className={headerMenu.itemstyle} href={headerMenu.itemurl}>{headerMenu.itemtext}</a>
              </li>
            ))}
          </ul>
          <ul>
            <li>
              <button className="login-button" onClick={this.toggleLoginModal}>
                Sign in / Sign up
              </button>
            </li>
          </ul>
        </nav>

        <LoginModal show={showLoginModal} onClose={this.toggleLoginModal} />
      </div>
    );
  }
}
